#!/usr/bin/env bash
# emptydirs.sh DIR : directories below DIR that contain nothing at all, relative paths, byte-wise sorted
dir=${1:-}
[ -d "$dir" ] || { echo "usage: emptydirs.sh DIR" >&2; exit 2; }
find "$dir" -mindepth 1 -type d -empty -printf '%P\n' | LC_ALL=C sort

