#!/bin/bash
# rmtmp.sh DIR : delete every regular *.tmp file below DIR and say how many
dir=${1:-}
[ -d "$dir" ] || { echo "usage: rmtmp.sh DIR" >&2; exit 2; }
n=$(find "$dir" -type f -name '*.tmp' -print0 | tr -cd '\0' | wc -c)
find "$dir" -type f -name '*.tmp' -print0 | xargs -0 -r rm -f --
echo "removed $n"
